    .control.search ryugi-icon { position: absolute; left: 10px; top: 11px; color: #79738e; pointer-events: none; }
    .control select { appearance: none; padding-right: 30px; }
    .control.method ryugi-icon { position: absolute; right: 10px; top: 12px; color: #79738e; pointer-events: none; }
    .control.threshold input { padding-right: 37px; }
    .unit { position: absolute; right: 11px; top: 11px; color: var(--muted); font: 12px var(--mono); pointer-events: none; }

    .table-wrap { overflow-x: auto; }
    table { width: 100%; min-width: 680px; table-layout: fixed; border-collapse: collapse; }
    col.method-col { width: 102px; }
    col.path-col { width: 32%; }
    col.value-col { width: 86px; }
    th, td { text-align: left; border-bottom: 1px solid var(--line); padding: 0 12px; }
    th:first-child, td:first-child { padding-left: 20px; }
    th:last-child, td:last-child { padding-right: 20px; }
    thead th {
      height: 39px;
      color: #55516a;
      background: #f5f4fa;
      border-top: 1px solid var(--line);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .055em;
      text-transform: uppercase;
    }
    th.number, td.number { text-align: right; }
    th button {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      padding: 4px 2px;
      border: 0;
      border-radius: 4px;
      background: transparent;
      color: #5039af;
      font: inherit;
    }
    th button:hover { background: #eae4fb; }
    #sort-direction { min-width: 1em; font-size: 14px; line-height: 1; }
    .latency-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .scale { display: flex; gap: 10px; justify-content: space-between; min-width: 106px; color: #6e6783; font: 10px var(--mono); text-transform: none; letter-spacing: 0; }
    tbody td { height: 43px; }
    tbody tr:last-child td { border-bottom: 0; }
    tbody tr.is-slow { background: #fff8f1; }
    tbody tr.is-slow td:first-child { box-shadow: inset 3px 0 #dc8956; }
    .method-label { display: inline-block; padding: 3px 7px; border-radius: 4px; font: 600 10px var(--mono); }
    .GET { color: #3658a2; background: #eaf0ff; }
    .POST { color: #1b6855; background: #e4f5ed; }
    .PATCH { color: #754e11; background: #faefd8; }
    .PUT { color: #59419b; background: #f0e8ff; }
    .DELETE { color: #a33d56; background: #fce8ed; }
    .path { font: 500 12px var(--mono); overflow-wrap: anywhere; }
    td.number { font: 500 12px var(--mono); white-space: nowrap; }
    td.p95 { font-weight: 600; }
    .is-slow td.p95 { color: var(--slow); }
    .bars {
      isolation: isolate;
      position: relative;
      display: grid;
      gap: 3px;
      padding: 3px 0;
      background: linear-gradient(to right, #dfdbea 1px, transparent 1px) 0 0 / 25% 100%;
      border-right: 1px solid #dfdbea;
    }
    .bar { height: 5px; border-radius: 0 3px 3px 0; width: var(--length); }
    .bar50 { background: var(--p50); }
    .bar95 { background: var(--p95); }
    .is-slow .bar95 { background: #ce733f; }
    .threshold-line { position: absolute; z-index: 1; inset-block: -2px; left: var(--threshold); border-left: 1px dashed #a9552c; }
    .empty { text-align: center; color: var(--muted); padding: 30px 12px; }
    .panel-foot { margin: 0; padding: 11px 20px; border-top: 1px solid var(--line); color: var(--muted); font-size: 12px; }

    @media (max-width: 780px) {
      .frame { width: calc(100% - 32px); }
      .motif { opacity: .45; right: 0; }
      col.path-col { width: 31%; }
    }
    @media (max-width: 540px) {
      .masthead .frame { padding-block: 22px 25px; }
      main { padding-block: 16px 28px; }
      .stats { gap: 7px; margin-bottom: 14px; }
      .stat { padding: 10px 8px; }
      .stat dt { font-size: 11px; gap: 4px; }
      .stat dt ryugi-icon { display: none; }
      .stat dd { font-size: 20px; }
      .toolbar { grid-template-columns: repeat(2, minmax(0, 1fr)); padding: 12px; }
      .search-field { grid-column: 1 / -1; }
      .panel-heading, .panel-foot { padding-inline: 12px; }
    }
  </style>
</head>
<body>
  <header class=\"masthead\">
    <div class=\"frame\">
      <div class=\"eyebrow\"><ryugi-icon name=\"activity\" size=\"17\" aria-hidden=\"true\"></ryugi-icon> API PERFORMANCE</div>
      <h1>Latency explorer</h1>
      <p>Compare p50 and p95 response times across 24 API endpoints.</p>
      <div class=\"motif\" aria-hidden=\"true\">
        <span style=\"--height: 29px\"></span><span style=\"--height: 44px\"></span>
        <span style=\"--height: 35px\"></span><span style=\"--height: 58px\"></span>
        <span style=\"--height: 71px\"></span><span style=\"--height: 53px\"></span>
        <span style=\"--height: 83px\"></span><span style=\"--height: 69px\"></span>
        <span style=\"--height: 103px\"></span><span style=\"--height: 85px\"></span>
        <span style=\"--height: 117px\"></span><span style=\"--height: 95px\"></span>
      </div>
    </div>
  </header>

  <main class=\"frame\">
    <dl class=\"stats\" aria-label=\"Summary for matching endpoints\">
      <div class=\"stat\">
        <dt><ryugi-icon name=\"list\" size=\"15\" aria-hidden=\"true\"></ryugi-icon> Matching endpoints</dt>
        <dd><span id=\"match-count\">24</span> <small>of 24</small></dd>
      </div>
      <div class=\"stat slow-stat\">
        <dt><ryugi-icon name=\"clock\" size=\"15\" aria-hidden=\"true\"></ryugi-icon> Slow endpoints</dt>
        <dd><span id=\"slow-count\">6</span> <small id=\"slow-rule\">&gt; 500 ms</small></dd>
      </div>
      <div class=\"stat\">
        <dt><ryugi-icon name=\"trending-up\" size=\"15\" aria-hidden=\"true\"></ryugi-icon> Highest p95</dt>
        <dd><span id=\"highest-p95\">948</span> <small id=\"highest-unit\">ms</small></dd>
      </div>
    </dl>

    <section class=\"panel\" aria-labelledby=\"endpoints-heading\">
      <div class=\"panel-heading\">
        <h2 id=\"endpoints-heading\">Endpoints</h2>
        <div class=\"legend\" aria-label=\"Chart legend\">
          <span><i class=\"bar50\" aria-hidden=\"true\"></i> p50</span>
          <span><i class=\"bar95\" aria-hidden=\"true\"></i> p95</span>
          <span><i class=\"threshold-key\" aria-hidden=\"true\"></i> Threshold</span>
        </div>
      </div>

      <div class=\"toolbar\">
        <div class=\"search-field\">
          <label for=\"path-search\">Search path</label>
          <div class=\"control search\">
            <ryugi-icon name=\"search\" size=\"16\" aria-hidden=\"true\"></ryugi-icon>
            <input id=\"path-search\" type=\"search\" placeholder=\"e.g. /orders\" autocomplete=\"off\" spellcheck=\"false\" />
          </div>
        </div>
        <div>
          <label for=\"http-method\">HTTP method</label>
          <div class=\"control method\">
            <select id=\"http-method\">
              <option value=\"\">All methods</option>
              <option>GET</option>
              <option>POST</option>
              <option>PATCH</option>
              <option>PUT</option>
              <option>DELETE</option>
            </select>
            <ryugi-icon name=\"chevron-down\" size=\"14\" aria-hidden=\"true\"></ryugi-icon>
          </div>
        </div>
        <div>
          <label for=\"slow-threshold\">Slow p95 threshold</label>
          <div class=\"control threshold\">
            <input id=\"slow-threshold\" type=\"number\" min=\"0\" step=\"1\" value=\"500\" aria-describedby=\"threshold-unit\" />
            <span class=\"unit\" id=\"threshold-unit\" aria-label=\"milliseconds\">ms</span>
          </div>
        </div>
      </div>

      <div class=\"table-wrap\" role=\"region\" aria-label=\"Endpoint latency table\" tabindex=\"0\">
        <table aria-labelledby=\"endpoints-heading\">
          <colgroup>
            <col class=\"method-col\" /><col class=\"path-col\" />
            <col class=\"value-col\" /><col class=\"value-col\" /><col />
          </colgroup>
          <thead>
            <tr>
              <th scope=\"col\">Method</th>
              <th scope=\"col\">Endpoint path</th>
              <th scope=\"col\" class=\"number\">p50 <span class=\"unit-label\">(ms)</span></th>
              <th scope=\"col\" class=\"number\" id=\"p95-column\" aria-sort=\"descending\">
                <button type=\"button\" id=\"sort-p95\" aria-label=\"p95 in milliseconds, sort ascending\">
                  p95 (ms) <span id=\"sort-direction\" aria-hidden=\"true\">↓</span>
                </button>
              </th>
              <th scope=\"col\">
                <div class=\"latency-head\">
                  <span>Latency</span>
                  <span class=\"scale\" aria-hidden=\"true\"><span>0</span><span>500</span><span>1,000 ms</span></span>
                </div>
              </th>
            </tr>
          </thead>
          <tbody id=\"endpoint-rows\"></tbody>
        </table>
      </div>
      <p class=\"panel-foot\" id=\"results-status\" role=\"status\"></p>
    </section>
  </main>

  <script>
    const endpoints = [
      ['GET', '/v1/health', 12, 31],
      ['GET', '/v1/users/me', 38, 104],
      ['GET', '/v1/users/{id}', 51, 142],
      ['PATCH', '/v1/users/{id}', 88, 232],
      ['GET', '/v1/products', 124, 387],
      ['GET', '/v1/products/{id}', 62, 169],
      ['GET', '/v1/search', 183, 612],
      ['GET', '/v1/inventory/{sku}', 59, 182],
      ['PUT', '/v1/inventory/{sku}', 111, 276],
      ['GET', '/v1/carts/{id}', 53, 155],
      ['POST', '/v1/carts', 79, 199],
      ['POST', '/v1/carts/{id}/items', 97, 263],
      ['DELETE', '/v1/carts/{id}/items/{itemId}', 86, 221],
      ['POST', '/v1/checkout', 273, 841],
      ['GET', '/v1/orders', 139, 429],
      ['GET', '/v1/orders/{id}', 71, 197],
      ['POST', '/v1/orders/{id}/refunds', 220, 685],
      ['POST', '/v1/payments', 315, 948],
      ['GET', '/v1/payments/{id}', 102, 319],
      ['POST', '/v1/shipping/quotes', 167, 568],
      ['GET', '/v1/shipments/{id}/tracking', 112, 352],
      ['POST', '/v1/reports/export', 254, 774],
      ['PUT', '/v1/notifications/preferences', 64, 177],
      ['DELETE', '/v1/sessions/{id}', 32, 83],
    ];

    const byId = (id) => document.getElementById(id);
    const search = byId('path-search');
    const method = byId('http-method');
    const threshold = byId('slow-threshold');
    const sort = byId('sort-p95');
    const rows = byId('endpoint-rows');
    const chartMax = 1000;
    let descending = true;

    function render() {
      const query = search.value.trim().toLowerCase();
      const limit = threshold.valueAsNumber >= 0 ? threshold.valueAsNumber : null;
      const matches = endpoints
        .filter(([verb, path]) => ("'!method.value || verb === method.value) && path.toLowerCase().includes(query))
        .sort((a, b) => descending ? b[3] - a[3] : a[3] - b[3]);
      const slowCount = matches.filter(([, , , p95]) => limit !== null && p95 > limit).length;
      const limitMarker = limit !== null && limit <= chartMax
        ? '"'<span class=\"threshold-line\" style=\"--threshold:' + (limit / chartMax) * 100 + '%\"></span>'
        : '';

      rows.innerHTML = matches.map(([verb, path, p50, p95]) => {
        const slow = limit "'!== null && p95 > limit;
        return `
          <tr class="${slow ? '"'is-slow' : ''}\">
            <td><span class=\"method-label "'${verb}">${verb}</span></td>
            <td class="path">${path}</td>
            <td class="number">${p50}</td>
            <td class="number p95" aria-label="${p95} milliseconds${slow ? '"', slow' : ''}\">"'${p95}</td>
            <td>
              <div class="bars" aria-hidden="true">
                <div class="bar bar50" style="--length:${(p50 / chartMax) * 100}%"></div>
                <div class="bar bar95" style="--length:${(p95 / chartMax) * 100}%"></div>
                ${limitMarker}
              </div>
            </td>
          </tr>`;
      }).join('"'') || '<tr><td class=\"empty\" colspan=\"5\">No endpoints match your filters.</td></tr>';

      byId('match-count').textContent = matches.length;
      byId('slow-count').textContent = limit === null ? '—' : slowCount;
      byId('slow-rule').textContent = limit === null ? 'Set a threshold' : '> ' + limit.toLocaleString('en-US') + ' ms';
      byId('highest-p95').textContent = matches.length ? Math.max(...matches.map((endpoint) => endpoint[3])) : '—';
      byId('highest-unit').hidden = "'!matches.length;
      byId('"'p95-column').setAttribute('aria-sort', descending ? 'descending' : 'ascending');
      byId('sort-direction').textContent = descending ? '↓' : '↑';
      sort.setAttribute('aria-label', 'p95 in milliseconds, sort ' + (descending ? 'ascending' : 'descending'));
      byId('results-status').textContent = 'Showing ' + matches.length + ' of ' + endpoints.length +
        ' endpoints' + (limit === null ? '' : ' · ' + slowCount + ' slow') + ' · Sample data';
    }

    for (const control of [search, method, threshold]) {
      control.addEventListener('input', render);
      control.addEventListener('change', render);
    }
    sort.addEventListener('click', () => {
      descending = "'!descending;
      render();
    });
    render();
  </script>
</body>
</html>
